insert into public.answer_option_translations (option_id, lang, text) values
('fcfc9615-dabf-b5e2-f2b6-533100a62705', 'de', 'Er habe die erste Stadt der Erde erbaut'),
('fcfc9615-dabf-b5e2-f2b6-533100a62705', 'en', 'He had built the first city on earth'),
('6eb519da-cff1-42a0-3280-70c9462e0aad', 'de', 'Er habe einen Mann getötet, der ihn verwundet hatte'),
('6eb519da-cff1-42a0-3280-70c9462e0aad', 'en', 'He had killed a man who wounded him'),
('0eb760fe-fa50-468d-e66e-fac0e25aa5e9', 'de', 'Er habe mehr Vieh als alle seine Brüder'),
('0eb760fe-fa50-468d-e66e-fac0e25aa5e9', 'en', 'He had more cattle than all his brothers'),
('f6fe003c-ec5c-bc83-8026-c14bcbdc5435', 'de', 'Er habe einen Löwen mit bloßen Händen erlegt'),
('f6fe003c-ec5c-bc83-8026-c14bcbdc5435', 'en', 'He had slain a lion with his bare hands'),
('d715f7e2-1482-d2ba-0dd4-feb8b08ef473', 'de', 'Als der weiseste Richter seiner Zeit'),
('d715f7e2-1482-d2ba-0dd4-feb8b08ef473', 'en', 'As the wisest judge of his time'),
('91395b12-fc1f-4f3d-5b7a-dc97348c0906', 'de', 'Als der erste Priester nach der Flut'),
('91395b12-fc1f-4f3d-5b7a-dc97348c0906', 'en', 'As the first priest after the flood'),
('8cb983d4-02f3-8ec8-7348-cd4d1a4459ed', 'de', 'Als ein gewaltiger Jäger vor dem HERRN'),
('8cb983d4-02f3-8ec8-7348-cd4d1a4459ed', 'en', 'As a mighty hunter before the LORD'),
('0ec88db0-965f-4225-c76c-33cbbd9e0fc1', 'de', 'Als ein friedfertiger Hirte des Ostens'),
('0ec88db0-965f-4225-c76c-33cbbd9e0fc1', 'en', 'As a peaceful shepherd of the East'),
('5e677869-4139-0d7c-06bf-4556e3690b2b', 'de', 'Ur in Chaldäa'),
('5e677869-4139-0d7c-06bf-4556e3690b2b', 'en', 'Ur in Chaldea'),
('4d02bcb2-a668-fd3e-c4b3-aa5d2a9327d2', 'de', 'Babel im Lande Schinar'),
('4d02bcb2-a668-fd3e-c4b3-aa5d2a9327d2', 'en', 'Babel in the land of Shinar'),
('d569b0c5-1429-50a9-7137-d69978866984', 'de', 'Ninive am Tigris'),
('d569b0c5-1429-50a9-7137-d69978866984', 'en', 'Nineveh on the Tigris'),
('cf918157-2406-f00e-0d80-00370b135d31', 'de', 'Hebron im Bergland'),
('cf918157-2406-f00e-0d80-00370b135d31', 'en', 'Hebron in the hill country'),
('4fd5c7ac-b84d-eebd-ce7f-e55e81f2649d', 'de', 'Weil Kanaan das Zelt niedergerissen hatte'),
('4fd5c7ac-b84d-eebd-ce7f-e55e81f2649d', 'en', 'Because Canaan had torn down the tent'),
('546dc8ee-a4d5-2257-00f7-467cd981c133', 'de', 'Weil Ham den Wein Noahs gestohlen hatte'),
('546dc8ee-a4d5-2257-00f7-467cd981c133', 'en', 'Because Ham had stolen Noah''s wine'),
('759ac460-4042-d600-d9a0-d44882f457c2', 'de', 'Weil Ham die Blöße seines Vaters gesehen und es weitererzählt hatte'),
('759ac460-4042-d600-d9a0-d44882f457c2', 'en', 'Because Ham saw his father''s nakedness and told it'),
