('3efb2511-5b35-520f-a42b-da816662f2d8', 'de', 'Ein Tagebuch seiner Taten'),
('3efb2511-5b35-520f-a42b-da816662f2d8', 'en', 'A journal of his deeds'),
('b1045b36-afec-2b81-8455-c9a8207dd1ab', 'de', 'Eine Abschrift dieses Gesetzes'),
('b1045b36-afec-2b81-8455-c9a8207dd1ab', 'en', 'A copy of this law'),
('1eb013e5-1648-66a6-40d8-4c7ab5865ff3', 'de', 'Eine Karte des Landes'),
('1eb013e5-1648-66a6-40d8-4c7ab5865ff3', 'en', 'A map of the land'),
('02227320-5ac1-29a9-e03c-73b1352e0ade', 'de', 'Er sollte dem Priester übergeben werden'),
('02227320-5ac1-29a9-e03c-73b1352e0ade', 'en', 'He should be handed to the priest'),
('e8233429-fab1-aeee-a82e-1a403f5caa3c', 'de', 'Er sollte zur Zwangsarbeit verurteilt werden'),
('e8233429-fab1-aeee-a82e-1a403f5caa3c', 'en', 'He should be sentenced to hard labor'),
('e192e816-3a39-4a63-aec1-ec3953a77888', 'de', 'Er sollte aus dem Land verbannt werden'),
('e192e816-3a39-4a63-aec1-ec3953a77888', 'en', 'He should be banished from the land'),
('91afb5c7-fcc0-eaf5-41a9-cab7ab88daf7', 'de', 'Die Männer der Stadt sollten ihn steinigen'),
('91afb5c7-fcc0-eaf5-41a9-cab7ab88daf7', 'en', 'The men of the city should stone him'),
('a165b854-c005-8416-fd2a-72f4c6fe4374', 'de', 'Er sollte am selben Tag begraben werden'),
('a165b854-c005-8416-fd2a-72f4c6fe4374', 'en', 'He should be buried the same day'),
('435bef74-41f0-6ab7-5041-254b87126137', 'de', 'Er sollte den Vögeln überlassen werden'),
('435bef74-41f0-6ab7-5041-254b87126137', 'en', 'He should be left to the birds'),
('7d172d16-9636-ac50-f1e3-9310b44e83bb', 'de', 'Er sollte drei Tage hängen bleiben'),
('7d172d16-9636-ac50-f1e3-9310b44e83bb', 'en', 'He should hang for three days'),
('f0e9f4af-bcc6-dda7-3590-f264711f7e34', 'de', 'Er sollte verbrannt werden'),
('f0e9f4af-bcc6-dda7-3590-f264711f7e34', 'en', 'He should be burned'),
('ac6f995a-93e1-cfe3-2f3b-19d7876de1db', 'de', 'Sie sollten die Kuh dem Priester opfern'),
('ac6f995a-93e1-cfe3-2f3b-19d7876de1db', 'en', 'They should sacrifice the heifer to the priest'),
('35966d7a-ce70-2fc1-c504-47f10958f827', 'de', 'Sie sollten die Kuh dem Herrn weihen'),
('35966d7a-ce70-2fc1-c504-47f10958f827', 'en', 'They should dedicate the heifer to the Lord'),
('47d85ebf-aafc-7ec7-3e30-527c03638f28', 'de', 'Sie sollten einer jungen Kuh in einem Bachtal das Genick brechen'),
('47d85ebf-aafc-7ec7-3e30-527c03638f28', 'en', 'They should break the neck of a heifer in a valley with a stream'),
('0b3da6bb-49f3-953e-f1b3-ac9779c6eb91', 'de', 'Sie sollten die Kuh dem nächsten Ort schenken'),
('0b3da6bb-49f3-953e-f1b3-ac9779c6eb91', 'en', 'They should give the heifer to the nearest town'),
('bfe7fe30-c2be-eaf0-d22f-6e320140f94b', 'de', 'Wir übergeben den Toten dem Herrn'),
('bfe7fe30-c2be-eaf0-d22f-6e320140f94b', 'en', 'We commit the dead to the Lord'),
('c034377b-e8cf-042b-5be5-77189a12fee8', 'de', 'Wir sühnen die Schuld des Landes'),
('c034377b-e8cf-042b-5be5-77189a12fee8', 'en', 'We atone for the guilt of the land'),
('7b05ba92-6d3e-f2f0-9957-cb484879eb28', 'de', 'Unsere Hände haben dieses Blut nicht vergossen'),
('7b05ba92-6d3e-f2f0-9957-cb484879eb28', 'en', 'Our hands have not shed this blood'),
('c7624ce9-0af3-fc2b-ded2-a50c17df35c0', 'de', 'Möge der Fluch von uns weichen'),
('c7624ce9-0af3-fc2b-ded2-a50c17df35c0', 'en', 'May the curse depart from us'),
('3564b8d7-0856-3696-03d7-c11df2f4bff5', 'de', 'Ein Maultier'),
('3564b8d7-0856-3696-03d7-c11df2f4bff5', 'en', 'A mule'),
('9ad5c2f7-d035-8fe6-3c0b-392403cf8940', 'de', 'Einen Esel'),
('9ad5c2f7-d035-8fe6-3c0b-392403cf8940', 'en', 'A donkey'),
('4471553c-c492-ad7f-c18c-837ba8fea9bc', 'de', 'Ein Pferd'),
('4471553c-c492-ad7f-c18c-837ba8fea9bc', 'en', 'A horse'),
('0bad2209-9611-f2df-afd3-bc7d9c5d8882', 'de', 'Ein Kamel'),
('0bad2209-9611-f2df-afd3-bc7d9c5d8882', 'en', 'A camel'),
('41748145-6732-0e31-4235-c083485ef1d6', 'de', 'Man sollte die Mutter zuerst nehmen'),
('41748145-6732-0e31-4235-c083485ef1d6', 'en', 'Take the mother first'),
('e223f07d-62d7-b670-6001-2d4b28d3d118', 'de', 'Man sollte die Mutter fliegen lassen und nur die Jungen nehmen'),
('e223f07d-62d7-b670-6001-2d4b28d3d118', 'en', 'Let the mother go and take only the young'),
('79db7cc4-c2d2-f847-cff3-2cdfd13b25af', 'de', 'Man sollte Mutter und Junge freilassen'),
('79db7cc4-c2d2-f847-cff3-2cdfd13b25af', 'en', 'Release both mother and young'),
('8dc39f21-5c94-4b87-8f5f-5b287af8c2b2', 'de', 'Man sollte das ganze Nest verschonen'),
('8dc39f21-5c94-4b87-8f5f-5b287af8c2b2', 'en', 'Spare the whole nest'),
('ded0604a-038b-5620-414c-d79ed53a317b', 'de', 'Quasten mit einer blauen Purpurschnur'),
('ded0604a-038b-5620-414c-d79ed53a317b', 'en', 'Tassels with a cord of blue'),
('231f64ff-c760-003e-6beb-edd61458d79f', 'de', 'Quasten aus reinem Goldfaden'),
('231f64ff-c760-003e-6beb-edd61458d79f', 'en', 'Tassels of pure gold thread'),
('33708884-ce5b-af00-b34d-6697bf507787', 'de', 'Quasten aus weißer Wolle'),
('33708884-ce5b-af00-b34d-6697bf507787', 'en', 'Tassels of white wool'),
('c6918da8-0bab-0e79-d6d4-642cc21f3036', 'de', 'Quasten mit roten Perlen'),
('c6918da8-0bab-0e79-d6d4-642cc21f3036', 'en', 'Tassels with red beads'),
('9f12d658-c146-bd0b-e65b-a4fe24bbc54a', 'de', 'Amalekiter und Midianiter'),
('9f12d658-c146-bd0b-e65b-a4fe24bbc54a', 'en', 'Amalekites and Midianites'),
('a8cba1d5-e8c9-ffd7-8461-f0f166f71db8', 'de', 'Edomiter und Ägypter'),
('a8cba1d5-e8c9-ffd7-8461-f0f166f71db8', 'en', 'Edomites and Egyptians'),
('ca891f02-3191-ba71-01cb-15255f6fbabf', 'de', 'Kanaaniter und Hetiter'),
('ca891f02-3191-ba71-01cb-15255f6fbabf', 'en', 'Canaanites and Hittites'),
('10c8d371-00f3-259d-2c84-9b4446a104a4', 'de', 'Ammoniter und Moabiter'),
('10c8d371-00f3-259d-2c84-9b4446a104a4', 'en', 'Ammonites and Moabites')
insert into public.answer_option_translations (option_id, lang, text) values
('e3686200-931e-c3aa-5288-f62aae1e4975', 'de', 'Weil er dir einst Wasser gab'),
('e3686200-931e-c3aa-5288-f62aae1e4975', 'en', 'Because he once gave you water'),
('40d8ea45-2697-fb75-12d9-fae6cb325901', 'de', 'Weil er dein Bruder ist'),
('40d8ea45-2697-fb75-12d9-fae6cb325901', 'en', 'Because he is your brother'),
('bf9151cf-8a2c-194a-2b0f-9c33470688b2', 'de', 'Weil er ein Nachkomme Abrahams ist'),
('bf9151cf-8a2c-194a-2b0f-9c33470688b2', 'en', 'Because he is a descendant of Abraham'),
('c44f5b50-824b-58e5-27b3-01d79b4b9e30', 'de', 'Weil er den Bund gehalten hat'),
('c44f5b50-824b-58e5-27b3-01d79b4b9e30', 'en', 'Because he kept the covenant'),
('639a4654-900e-e778-ec54-83207faf2727', 'de', 'Sein Feld bestellen'),
('639a4654-900e-e778-ec54-83207faf2727', 'en', 'Till his field'),
('7ffa1d4d-3e7b-fc1b-398d-8fcb3d2ecad8', 'de', 'Zum Fest nach Silo reisen'),
('7ffa1d4d-3e7b-fc1b-398d-8fcb3d2ecad8', 'en', 'Travel to the feast in Shiloh'),
('0132910e-539b-03e9-a8bd-77497d46fce6', 'de', 'Tribut zahlen'),
('0132910e-539b-03e9-a8bd-77497d46fce6', 'en', 'Pay tribute'),
('0287c5d0-8b64-72d2-b3fa-04d417fc9497', 'de', 'In den Krieg ziehen oder mit Pflichten belastet werden'),
('0287c5d0-8b64-72d2-b3fa-04d417fc9497', 'en', 'Go to war or be burdened with any duty'),
('fb0a9304-20cf-5cd5-d88f-2bb4c035351a', 'de', 'Den unteren oder oberen Mühlstein'),
('fb0a9304-20cf-5cd5-d88f-2bb4c035351a', 'en', 'The lower or upper millstone'),
('729f0eb0-73f8-ef99-2cfe-9db0f185aeec', 'de', 'Den Mantel eines Reichen'),
('729f0eb0-73f8-ef99-2cfe-9db0f185aeec', 'en', 'The cloak of a rich man'),
('5695af8a-bfd9-2950-4d1f-f7a75ececbcc', 'de', 'Das Saatgut des Feldes'),
('5695af8a-bfd9-2950-4d1f-f7a75ececbcc', 'en', 'The seed grain of the field'),
('930ee309-a9f7-23a6-9bcf-bee59301297c', 'de', 'Den einzigen Ochsen'),
('930ee309-a9f7-23a6-9bcf-bee59301297c', 'en', 'The only ox'),
('d33b2596-39c9-1633-8765-c2e9823780b0', 'de', 'Sie legte ihm Asche aufs Haupt'),
('d33b2596-39c9-1633-8765-c2e9823780b0', 'en', 'She put ashes on his head'),
('4b467023-db86-5c58-a925-a10fcdeba1dc', 'de', 'Sie verfluchte ihn am Stadttor'),
('4b467023-db86-5c58-a925-a10fcdeba1dc', 'en', 'She cursed him at the city gate'),
('35154fa1-eff6-e0b0-270c-be2ca54e8158', 'de', 'Sie zog ihm den Schuh aus und spuckte ihm ins Gesicht'),
('35154fa1-eff6-e0b0-270c-be2ca54e8158', 'en', 'She pulled off his sandal and spat in his face'),
('177da550-825c-0258-d1b7-be2933af4ef6', 'de', 'Sie zerriss sein Gewand vor den Ältesten'),
('177da550-825c-0258-d1b7-be2933af4ef6', 'en', 'She tore his garment before the elders'),
('19b936d9-374c-69e1-0e8d-bfac6bea70c1', 'de', 'Moab'),
('19b936d9-374c-69e1-0e8d-bfac6bea70c1', 'en', 'Moab'),
('46f03b49-e041-a21d-4c82-fadd13eb63d0', 'de', 'Edom'),
('46f03b49-e041-a21d-4c82-fadd13eb63d0', 'en', 'Edom'),
('cf11b1e0-7d06-3ff6-a248-d55cb5187f0e', 'de', 'Midian'),
('cf11b1e0-7d06-3ff6-a248-d55cb5187f0e', 'en', 'Midian'),
('5c2ea210-4406-7ecc-6e69-a393a04173e3', 'de', 'Amalek'),
('5c2ea210-4406-7ecc-6e69-a393a04173e3', 'en', 'Amalek'),
('82528d31-e1f6-f331-b482-0c774b6568dc', 'de', 'Ich habe die Gebote gehalten'),
('82528d31-e1f6-f331-b482-0c774b6568dc', 'en', 'I have kept the commandments'),
('2db6a6dd-d9f7-820b-d141-d066af9f77f0', 'de', 'Der Herr ist einzig und allein'),
('2db6a6dd-d9f7-820b-d141-d066af9f77f0', 'en', 'The Lord is one and alone'),
('0a4f9835-bf6a-daf0-9e1e-334c73011dbb', 'de', 'Gepriesen sei der Gott Israels'),
('0a4f9835-bf6a-daf0-9e1e-334c73011dbb', 'en', 'Blessed be the God of Israel'),
('8509fc4c-ca09-b9d7-a416-50e8ab0490c0', 'de', 'Ein umherirrender Aramäer war mein Vater'),
('8509fc4c-ca09-b9d7-a416-50e8ab0490c0', 'en', 'A wandering Aramean was my father'),
('e31063e4-3e51-7d9a-0da7-3d032f5da446', 'de', 'Im Land Moab, und der Herr begrub ihn im Tal'),
('e31063e4-3e51-7d9a-0da7-3d032f5da446', 'en', 'In the land of Moab, and the Lord buried him in the valley'),
('53e82c4a-d80b-b5df-3dfd-24a3b9a66ff6', 'de', 'Am Jordan, und die Ältesten begruben ihn'),
('53e82c4a-d80b-b5df-3dfd-24a3b9a66ff6', 'en', 'At the Jordan, and the elders buried him'),
('88ffce41-24c5-723d-eb40-a81802891013', 'de', 'Auf dem Berg Sinai, und Aaron begrub ihn'),
('88ffce41-24c5-723d-eb40-a81802891013', 'en', 'On Mount Sinai, and Aaron buried him'),
('f4bc4975-919e-8c38-4b89-df3c31027c4a', 'de', 'In der Wüste Zin, und Josua begrub ihn'),
('f4bc4975-919e-8c38-4b89-df3c31027c4a', 'en', 'In the wilderness of Zin, and Joshua buried him'),
('6194fbfd-72f6-c9d1-3812-c0d5bb300d06', 'de', 'Hundertzwanzig Jahre, sein Auge ungetrübt und die Kraft ungebrochen'),
('6194fbfd-72f6-c9d1-3812-c0d5bb300d06', 'en', 'One hundred twenty years, his eye undimmed and vigor unabated'),
('0a2a7738-ad6d-8ff7-d1e2-e88f3371441b', 'de', 'Hundertzehn Jahre, erblindet und schwach'),
('0a2a7738-ad6d-8ff7-d1e2-e88f3371441b', 'en', 'One hundred ten years, blind and weak'),
('a1fb2688-9f63-4fec-99a9-129274517905', 'de', 'Achtzig Jahre, gebrechlich geworden'),
('a1fb2688-9f63-4fec-99a9-129274517905', 'en', 'Eighty years, grown frail'),
('827a139d-9a76-639e-763b-9e1ce9ef32b3', 'de', 'Hundertfünfzig Jahre, aber noch rüstig'),
('827a139d-9a76-639e-763b-9e1ce9ef32b3', 'en', 'One hundred fifty years, yet still hale'),
('53f130fa-4572-ca63-f193-ffd89dfa93a6', 'de', 'Vom Berg Gilboa über der Ebene'),
('53f130fa-4572-ca63-f193-ffd89dfa93a6', 'en', 'From Mount Gilboa above the plain'),
('c8482850-397f-5466-6807-7342ac709153', 'de', 'Vom Berg Horeb in der Wüste'),
('c8482850-397f-5466-6807-7342ac709153', 'en', 'From Mount Horeb in the wilderness'),
('c47546c7-54eb-64e2-34bc-7d0971b0da3d', 'de', 'Vom Berg Nebo, dem Gipfel des Pisga'),
('c47546c7-54eb-64e2-34bc-7d0971b0da3d', 'en', 'From Mount Nebo, the top of Pisgah'),
('276b28dc-adce-2a94-dbf6-35c9b0994736', 'de', 'Vom Berg Hor am Rand Edoms'),
('276b28dc-adce-2a94-dbf6-35c9b0994736', 'en', 'From Mount Hor at the edge of Edom'),
('d769d86f-bc16-ec9d-b4f6-dbaeca3cc1a5', 'de', 'Er legte seine Hand unter Boas'' Hüfte'),
('d769d86f-bc16-ec9d-b4f6-dbaeca3cc1a5', 'en', 'He put his hand under Boaz''s thigh'),
('fcbeff00-c503-ab64-be67-fc4f8d40975e', 'de', 'Er zog seinen Schuh aus und gab ihn Boas'),
('fcbeff00-c503-ab64-be67-fc4f8d40975e', 'en', 'He drew off his sandal and gave it to Boaz'),
('d9342267-6360-8c71-7181-1170c5094d9f', 'de', 'Er warf einen Stein auf den Steinhaufen'),
('d9342267-6360-8c71-7181-1170c5094d9f', 'en', 'He cast a stone upon the heap'),
('919f41cb-bd13-0b9d-73fe-64dd9cdad815', 'de', 'Er zerriss seinen Mantel vor den Ältesten'),
('919f41cb-bd13-0b9d-73fe-64dd9cdad815', 'en', 'He tore his cloak before the elders'),
('05638d77-5728-6fdf-3af7-4d19322f28ab', 'de', 'Friede sei diesem Hause'),
('05638d77-5728-6fdf-3af7-4d19322f28ab', 'en', 'Peace be to this house'),
('33480f2e-4a98-4b4a-5b33-6182cb0c48b8', 'de', 'Gott stärke eure Hände'),
('33480f2e-4a98-4b4a-5b33-6182cb0c48b8', 'en', 'God strengthen your hands'),
('e6ff8515-b14c-9a75-022f-0774c6bb34e4', 'de', 'Der HERR sei mit euch'),
('e6ff8515-b14c-9a75-022f-0774c6bb34e4', 'en', 'The LORD be with you'),
('c2fa1348-9634-2599-272d-7e4748016aed', 'de', 'Segen sei über eurer Ernte'),
('c2fa1348-9634-2599-272d-7e4748016aed', 'en', 'Blessing be upon your harvest'),
('68537b3f-9cc0-17e8-1fdc-a55f3612da63', 'de', 'Mit einem geliehenen Krug'),
('68537b3f-9cc0-17e8-1fdc-a55f3612da63', 'en', 'With a borrowed jar'),
('d834fe17-6dfc-f602-0c77-6a60d32ed1d8', 'de', 'Mit ihrem Erntesack aus Leinen'),
('d834fe17-6dfc-f602-0c77-6a60d32ed1d8', 'en', 'With her linen harvest sack'),
('e9d99075-e058-b581-0310-111bed39b43b', 'de', 'Mit dem Tuch, das sie umhatte'),
('e9d99075-e058-b581-0310-111bed39b43b', 'en', 'With the mantle she was wearing'),
('fefd1199-a57d-2778-1311-c1d3b896c481', 'de', 'Mit dem Saum ihres Mantels'),
('fefd1199-a57d-2778-1311-c1d3b896c481', 'en', 'With the hem of her cloak'),
('364cca35-00a7-8bab-5635-4838b13adfa8', 'de', 'Zehn Maß Gerste'),
('364cca35-00a7-8bab-5635-4838b13adfa8', 'en', 'Ten measures of barley'),
('7701f3d8-fe8c-b506-7bc9-b637e9f7ddf3', 'de', 'Sechs Maß Gerste'),
('7701f3d8-fe8c-b506-7bc9-b637e9f7ddf3', 'en', 'Six measures of barley'),
('11f98551-bc55-0dc2-d783-98bd4d0eb58f', 'de', 'Drei Maß Gerste'),
('11f98551-bc55-0dc2-d783-98bd4d0eb58f', 'en', 'Three measures of barley'),
('479946fc-c829-7865-b2e4-fab190a643c4', 'de', 'Ein Epha Gerste'),
('479946fc-c829-7865-b2e4-fab190a643c4', 'en', 'An ephah of barley'),
('54b6a1d0-b6d8-d00e-8641-015f3b245344', 'de', 'Debora, denn ich klage'),
('54b6a1d0-b6d8-d00e-8641-015f3b245344', 'en', 'Deborah, for I lament'),
('ebb94d81-b05d-488b-41da-02755156d4da', 'de', 'Mara, denn bitter hat mich der Allmächtige gemacht'),
('ebb94d81-b05d-488b-41da-02755156d4da', 'en', 'Mara, for the Almighty has made me bitter'),
('174c9464-0b2c-9618-00ef-0bc819275f0b', 'de', 'Lea, denn ich bin verschmäht'),
('174c9464-0b2c-9618-00ef-0bc819275f0b', 'en', 'Leah, for I am spurned'),
('52a78eb0-413c-f136-c18a-4993296277fc', 'de', 'Bochim, denn hier weinte ich'),
('52a78eb0-413c-f136-c18a-4993296277fc', 'en', 'Bochim, for here I wept'),
('8ee673dc-fe54-5a8f-12aa-7bebd9db0724', 'de', 'Sie sei wie Rebekka am Brunnen'),
('8ee673dc-fe54-5a8f-12aa-7bebd9db0724', 'en', 'May she be like Rebekah at the well'),
('97e56b83-d7f4-6e73-421e-4249724afb79', 'de', 'Sie sei wie Mirjam mit der Pauke'),
('97e56b83-d7f4-6e73-421e-4249724afb79', 'en', 'May she be like Miriam with the timbrel'),
('73d29c5c-7391-0e3c-ac16-dfde5923e7a4', 'de', 'Sie sei wie Rahel und Lea, die das Haus Israel bauten'),
('73d29c5c-7391-0e3c-ac16-dfde5923e7a4', 'en', 'May she be like Rachel and Leah who built the house of Israel'),
('b885129f-f6bf-387f-99aa-3b1f8f270cdd', 'de', 'Sie sei wie Sara, die Isaak gebar'),
('b885129f-f6bf-387f-99aa-3b1f8f270cdd', 'en', 'May she be like Sarah who bore Isaac'),
('cb0cc1a6-49fe-ae03-2c24-bcf3963d1b26', 'de', 'Sich zu seinem Haupt legen'),
('cb0cc1a6-49fe-ae03-2c24-bcf3963d1b26', 'en', 'Lie down at his head'),
('4c00e374-fa75-5848-e6b5-3871d4181e21', 'de', 'Ihn beim Namen laut rufen'),
('4c00e374-fa75-5848-e6b5-3871d4181e21', 'en', 'Call him loudly by name'),
('5fd99549-f382-3d48-338d-8ca3955e757a', 'de', 'Seine Füße aufdecken und sich hinlegen'),
('5fd99549-f382-3d48-338d-8ca3955e757a', 'en', 'Uncover his feet and lie down'),
('9251b0c0-b36f-a1c3-434a-1fea24764a82', 'de', 'Ihm Wasser reichen und dann fliehen'),
('9251b0c0-b36f-a1c3-434a-1fea24764a82', 'en', 'Bring him water and then flee'),
('0c816353-c1da-bd1c-80e0-0e5a3af374c0', 'de', 'Ich bin die Moabiterin, die Ähren las'),
('0c816353-c1da-bd1c-80e0-0e5a3af374c0', 'en', 'I am the Moabitess who gleaned ears'),
('a623e3a3-fa73-41d7-ef54-70ee46d5d40e', 'de', 'Ich suche nur ein Nachtlager'),
('a623e3a3-fa73-41d7-ef54-70ee46d5d40e', 'en', 'I seek only a place to lodge'),
('00e8e120-9b10-5066-d57f-9dfb2ce094b6', 'de', 'Breite deinen Flügel über deine Magd, denn du bist Löser'),
('00e8e120-9b10-5066-d57f-9dfb2ce094b6', 'en', 'Spread your wing over your maidservant, for you are a redeemer'),
('392cd5aa-1535-7cdd-90da-4ba7790e0f66', 'de', 'Fürchte dich nicht, ich bin nur eine Fremde'),
('392cd5aa-1535-7cdd-90da-4ba7790e0f66', 'en', 'Do not fear, I am only a stranger'),
('135bb427-9253-7b2b-32ac-83ca80cc5f44', 'de', 'Sie brachte es zum Priester zur Weihe'),
('135bb427-9253-7b2b-32ac-83ca80cc5f44', 'en', 'She brought it to the priest for dedication'),
('7cf57501-4eea-b21c-d93b-52eaf81a547c', 'de', 'Sie gab es Boas'' Verwandten zu erziehen'),
('7cf57501-4eea-b21c-d93b-52eaf81a547c', 'en', 'She gave it to Boaz''s kin to raise'),
('fd191e9c-5d90-709a-2695-9d164bceaa54', 'de', 'Sie nahm es auf ihren Schoß und wurde seine Pflegerin'),
('fd191e9c-5d90-709a-2695-9d164bceaa54', 'en', 'She took it to her bosom and became its nurse'),
('0ab62240-071a-f867-bb60-c67ae252fb30', 'de', 'Sie zog mit ihm nach Moab zurück'),
('0ab62240-071a-f867-bb60-c67ae252fb30', 'en', 'She returned with it to Moab'),
('c1d92ed1-e416-ee52-6512-9e206df6abb6', 'de', 'Dass sie den HERRN von Herzen fürchte'),
('c1d92ed1-e416-ee52-6512-9e206df6abb6', 'en', 'That she feared the LORD with all her heart'),
('e0429730-7b25-e7b6-3ede-288c41dbeea9', 'de', 'Dass er ein naher Löser ihres Hauses sei'),
('e0429730-7b25-e7b6-3ede-288c41dbeea9', 'en', 'That he was a near redeemer of her house'),
('1ed8bd6b-8c3d-9458-8d41-a85f23c7e2a0', 'de', 'Dass sie treu die Felder bestellt habe'),
('1ed8bd6b-8c3d-9458-8d41-a85f23c7e2a0', 'en', 'That she had faithfully tended the fields'),
('2bc64c23-1d29-6b00-d84a-2e91d221569c', 'de', 'Dass Noomi ihr das befohlen habe'),
('2bc64c23-1d29-6b00-d84a-2e91d221569c', 'en', 'That Naomi had commanded her'),
('a3f36955-c52a-4551-9465-584941e0779d', 'de', 'Sechs Maß Gerste von Boas'),
('a3f36955-c52a-4551-9465-584941e0779d', 'en', 'Six measures of barley from Boaz'),
('f4cb7665-5534-71f3-1843-e796bc1e03eb', 'de', 'Brot und geröstetes Korn'),
('f4cb7665-5534-71f3-1843-e796bc1e03eb', 'en', 'Bread and parched grain'),
('8e7e82d3-773f-22aa-f940-b3609c4b6321', 'de', 'Einen Krug Wein und Öl'),
('8e7e82d3-773f-22aa-f940-b3609c4b6321', 'en', 'A jar of wine and oil'),
('0a1e6967-867e-e63c-37dd-b6d328924b21', 'de', 'Ein Bündel gebundener Ähren'),
('0a1e6967-867e-e63c-37dd-b6d328924b21', 'en', 'A bundle of bound ears'),
('24cc8efa-fc30-feb8-e2a6-a12b7a4744db', 'de', 'Feigenkuchen und Rosinen'),
('24cc8efa-fc30-feb8-e2a6-a12b7a4744db', 'en', 'Fig cakes and raisins'),
('518b2950-66e1-8cd7-1254-7d7a7dc08761', 'de', 'Brei aus Linsen und Öl'),
('518b2950-66e1-8cd7-1254-7d7a7dc08761', 'en', 'Pottage of lentils and oil'),
('95067c19-a84e-2e08-3c74-caa0d25877ba', 'de', 'Brot in Essig getaucht und geröstetes Korn'),
('95067c19-a84e-2e08-3c74-caa0d25877ba', 'en', 'Bread dipped in vinegar and parched grain'),
('453116a0-8022-cf6d-c7fa-b48476850f15', 'de', 'Ein Lamm vom Feuer und Milch'),
('453116a0-8022-cf6d-c7fa-b48476850f15', 'en', 'A lamb from the fire and milk'),
('acbda780-bb00-5591-240c-89714c8dd1a8', 'de', 'Weil die Ältesten es so verlangten'),
('acbda780-bb00-5591-240c-89714c8dd1a8', 'en', 'Because the elders demanded it so'),
('6b08694d-062b-4ca1-0557-95b8ca96e7f9', 'de', 'Weil Noomi es ausdrücklich wünschte'),
('6b08694d-062b-4ca1-0557-95b8ca96e7f9', 'en', 'Because Naomi expressly wished it'),
('da7e6ee3-578c-9a06-c17d-0774ea98ba1b', 'de', 'Weil dieser vor ihm das Löserecht hatte'),
('da7e6ee3-578c-9a06-c17d-0774ea98ba1b', 'en', 'Because that man held the right of redemption before him'),
('85b4b9e5-ecdb-cf14-7432-7692165f192b', 'de', 'Weil dieser reicher als Boas war'),
('85b4b9e5-ecdb-cf14-7432-7692165f192b', 'en', 'Because that man was richer than Boaz'),
('fb298294-7ae1-30f5-c0ce-9bcb0bad6b97', 'de', 'Er wollte Betlehem verlassen'),
('fb298294-7ae1-30f5-c0ce-9bcb0bad6b97', 'en', 'He wished to leave Bethlehem'),
('795b5674-0e68-7b2a-55d4-5177009e0bd8', 'de', 'Er hatte kein Geld für den Kauf'),
('795b5674-0e68-7b2a-55d4-5177009e0bd8', 'en', 'He had no money for the purchase'),
('e3092075-3c0f-9877-c5f2-7de67ee59cb4', 'de', 'Er fürchtete, sein eigenes Erbe zu verderben'),
('e3092075-3c0f-9877-c5f2-7de67ee59cb4', 'en', 'He feared to ruin his own inheritance'),
('e546e375-ace7-3dd4-0511-416503c332a0', 'de', 'Er hasste die Moabiter'),
('e546e375-ace7-3dd4-0511-416503c332a0', 'en', 'He hated the Moabites'),
('aaadc911-ec7d-2641-4f9f-60630985eb11', 'de', 'Ich kehre nie mehr nach Moab zurück'),
('aaadc911-ec7d-2641-4f9f-60630985eb11', 'en', 'I will never return to Moab again'),
('e4876ad4-39fb-b1ed-6dd0-1ecd3b37137f', 'de', 'Ich diene dir bis zur Ernte'),
('e4876ad4-39fb-b1ed-6dd0-1ecd3b37137f', 'en', 'I will serve you until the harvest'),
('fd32feca-a8a8-e175-8c5c-5661a50cf055', 'de', 'Wo du stirbst, da sterbe auch ich und werde begraben'),
('fd32feca-a8a8-e175-8c5c-5661a50cf055', 'en', 'Where you die, I will die and be buried'),
('2bf7df9c-043d-ae10-fe54-c3b3e2840911', 'de', 'Dein Gott gebe mir einen Sohn'),
('2bf7df9c-043d-ae10-fe54-c3b3e2840911', 'en', 'May your God give me a son'),
('7888b8e8-6a72-cb18-707b-f8c2a032b988', 'de', 'Sie zahlte Noomis Schulden am Tor'),
('7888b8e8-6a72-cb18-707b-f8c2a032b988', 'en', 'She paid Naomi''s debts at the gate'),
('e08e24fe-d725-dd5b-5f0f-2ba2ce4f645e', 'de', 'Sie heilte Noomis Bitterkeit mit Trost'),
('e08e24fe-d725-dd5b-5f0f-2ba2ce4f645e', 'en', 'She healed Naomi''s bitterness with comfort'),
('525a0014-d5ab-b8ca-2154-8bd766c8516e', 'de', 'Sie verließ Vater und Mutter und kam zu einem fremden Volk'),
('525a0014-d5ab-b8ca-2154-8bd766c8516e', 'en', 'She left father and mother and came to a people she did not know'),
('49fd3a42-98c8-15d6-585c-c2864b32be5f', 'de', 'Sie brachte reiche Ernte in Noomis Haus'),
('49fd3a42-98c8-15d6-585c-c2864b32be5f', 'en', 'She brought a rich harvest into Naomi''s house'),
('1b296daf-4d28-24f7-bfc2-c7ee607ae299', 'de', 'Ihr das beste Feld allein zuweisen'),
('1b296daf-4d28-24f7-bfc2-c7ee607ae299', 'en', 'To assign her the best field alone'),
('24d54a5e-ff4f-9b08-a31b-b083ce777d7e', 'de', 'Aus den Garben Ähren fallen lassen für sie'),
('24d54a5e-ff4f-9b08-a31b-b083ce777d7e', 'en', 'To let ears fall from the bundles for her'),
('c97ac68a-22ac-44c4-cf80-ca1587f7859d', 'de', 'Sie zur Tenne mitzunehmen'),
('c97ac68a-22ac-44c4-cf80-ca1587f7859d', 'en', 'To take her along to the threshing floor'),
('4dc32fdf-348b-af65-92f3-3ef296884187', 'de', 'Ihr einen Lohn in Silber zu geben'),
('4dc32fdf-348b-af65-92f3-3ef296884187', 'en', 'To give her a wage in silver'),
('98eec07b-ad42-f8bf-4ae3-7068fa6aa77c', 'de', 'Er zersplitterte durch einen Blitz'),
('98eec07b-ad42-f8bf-4ae3-7068fa6aa77c', 'en', 'He was shattered by lightning'),
('8f8014f5-ceef-e8d2-20f7-0a33926ddfd1', 'de', 'Er verbrannte in der Nacht'),
('8f8014f5-ceef-e8d2-20f7-0a33926ddfd1', 'en', 'He burned during the night'),
('51664230-5621-f0dd-81fa-6a1131b6f04d', 'de', 'Er verschwand spurlos aus dem Tempel'),
('51664230-5621-f0dd-81fa-6a1131b6f04d', 'en', 'He vanished without trace from the temple'),
('18ec2f58-8218-4fee-2c78-6c82525632d1', 'de', 'Er lag umgestürzt auf dem Angesicht vor der Lade'),
('18ec2f58-8218-4fee-2c78-6c82525632d1', 'en', 'He lay fallen on his face before the Ark'),
('5e09a276-3fc6-bfff-9642-99d2183ae4ee', 'de', 'Seine Krone und sein Zepter'),
('5e09a276-3fc6-bfff-9642-99d2183ae4ee', 'en', 'His crown and his scepter'),
('e7b0ddf4-f10b-698b-1b3e-6e4629bbdb93', 'de', 'Sein Kopf und beide Handflächen'),
('e7b0ddf4-f10b-698b-1b3e-6e4629bbdb93', 'en', 'His head and both palms of his hands'),
('d76800b4-1014-03ec-dbcf-10547c2d74e3', 'de', 'Seine Füße und sein rechter Arm'),
('d76800b4-1014-03ec-dbcf-10547c2d74e3', 'en', 'His feet and his right arm'),
('b74cc880-bffd-8c12-612a-b36e3080dde6', 'de', 'Sein Bauch und seine Schulter'),
('b74cc880-bffd-8c12-612a-b36e3080dde6', 'en', 'His belly and his shoulder'),
('18237662-3fc1-11c5-ed53-256c916e90fb', 'de', 'Er sandte Heuschrecken über ihr Land'),
('18237662-3fc1-11c5-ed53-256c916e90fb', 'en', 'He sent locusts over their land'),
('6a6f2ff6-cc12-2f1f-5997-2bfaad708d06', 'de', 'Er schlug sie mit Beulen'),
('6a6f2ff6-cc12-2f1f-5997-2bfaad708d06', 'en', 'He struck them with tumors'),
('4e81e22d-3f9a-f301-5b3b-acbdd762ed37', 'de', 'Er schlug ihre Erstgeburt'),
('4e81e22d-3f9a-f301-5b3b-acbdd762ed37', 'en', 'He struck their firstborn'),
('5d049da8-4cbd-1285-cbc0-49d071a44c6f', 'de', 'Er ließ das Wasser zu Blut werden'),
('5d049da8-4cbd-1285-cbc0-49d071a44c6f', 'en', 'He turned their water to blood'),
('b4a8c92e-6bd9-e013-9d31-82a52b379b3c', 'de', 'Ein Bild ihres Gottes aus Gold'),
('b4a8c92e-6bd9-e013-9d31-82a52b379b3c', 'en', 'An image of their god in gold'),
('998815c1-6624-3783-0bcf-8e3ef66e4e8c', 'de', 'Sieben goldene Kälber'),
('998815c1-6624-3783-0bcf-8e3ef66e4e8c', 'en', 'Seven golden calves'),
('3a3cfd49-74d7-3c6a-8ae7-d771d9a18a3a', 'de', 'Fünf goldene Beulen und fünf goldene Mäuse'),
('3a3cfd49-74d7-3c6a-8ae7-d771d9a18a3a', 'en', 'Five golden tumors and five golden mice'),
('d19c90a5-a4f2-e260-7a8d-6194098a0e45', 'de', 'Zehn silberne Schalen'),
('d19c90a5-a4f2-e260-7a8d-6194098a0e45', 'en', 'Ten silver bowls'),
('11b7bf98-54e6-17fd-59e1-15f5c6ca0d38', 'de', 'Die Lade auf einem Floß den Fluss hinabtreiben lassen'),
('11b7bf98-54e6-17fd-59e1-15f5c6ca0d38', 'en', 'Float the Ark down the river on a raft'),
('84cc7338-63e8-95bb-1ee8-b20ce09af2f1', 'de', 'Priester über der Lade würfeln lassen'),
('84cc7338-63e8-95bb-1ee8-b20ce09af2f1', 'en', 'Have priests dice over the Ark'),
('b4aabbad-3365-21a1-d3d2-444155679f60', 'de', 'Los werfen zwischen den fünf Städten'),
('b4aabbad-3365-21a1-d3d2-444155679f60', 'en', 'Cast lots among the five cities'),
('e8a3a82c-65a3-6029-8f60-6dc0920d12aa', 'de', 'Zwei säugende Kühe ohne Führung an den Wagen spannen'),
('e8a3a82c-65a3-6029-8f60-6dc0920d12aa', 'en', 'Yoke two milk cows with no driver to the cart'),
('7c261466-a341-6703-c9b3-46469938602b', 'de', 'Ins Feld der Philister'),
('7c261466-a341-6703-c9b3-46469938602b', 'en', 'Into the field of the Philistines'),
('b3719430-2af3-0835-daaf-bad304af57ae', 'de', 'Geradewegs nach Bet-Schemesch'),
('b3719430-2af3-0835-daaf-bad304af57ae', 'en', 'Straight toward Beth-shemesh'),
('44adf09e-0eb9-3440-877a-368c42627670', 'de', 'Hinauf nach Ekron'),
('44adf09e-0eb9-3440-877a-368c42627670', 'en', 'Up to Ekron'),
('6359e582-a091-441f-89c8-b62b86d25051', 'de', 'Zurück nach Aschdod'),
('6359e582-a091-441f-89c8-b62b86d25051', 'en', 'Back to Ashdod'),
('d58351ad-b26c-37ee-b56a-26dba852a0a9', 'de', 'Weil sie sie nicht mit Opfern empfingen'),
('d58351ad-b26c-37ee-b56a-26dba852a0a9', 'en', 'Because they did not receive it with offerings'),
('698b9253-190f-33ba-3268-2109759817b9', 'de', 'Weil sie sie in einen Götzentempel stellten'),
('698b9253-190f-33ba-3268-2109759817b9', 'en', 'Because they set it in an idol temple'),
('ba3bd046-e09e-1a30-78f8-f5362a7de951', 'de', 'Weil sie sie zurück zu den Philistern sandten'),
('ba3bd046-e09e-1a30-78f8-f5362a7de951', 'en', 'Because they sent it back to the Philistines'),
('c127c3d8-7e20-e576-e2f0-10cf63fa92cb', 'de', 'Weil sie in die Lade des HERRN geschaut hatten'),
('c127c3d8-7e20-e576-e2f0-10cf63fa92cb', 'en', 'Because they had looked into the Ark of the LORD'),
('ca19d1ae-433e-7856-8e19-7684b03eedbc', 'de', 'Mit dem Holz des Wagens'),
('ca19d1ae-433e-7856-8e19-7684b03eedbc', 'en', 'With the wood of the cart'),
('3a1626e1-7653-d463-9138-60adac054b14', 'de', 'Mit Kohlen vom Altar zu Silo'),
('3a1626e1-7653-d463-9138-60adac054b14', 'en', 'With coals from the altar at Shiloh'),
('4535b140-9f59-e50b-382f-5d92f891a7a4', 'de', 'Mit Holz aus dem heiligen Hain'),
('4535b140-9f59-e50b-382f-5d92f891a7a4', 'en', 'With wood from a sacred grove'),
('86d57c32-649d-f8d6-cf6a-4f33da53d0df', 'de', 'Mit Zedern aus dem Libanon'),
('86d57c32-649d-f8d6-cf6a-4f33da53d0df', 'en', 'With cedars from Lebanon'),
('844f44c4-7a0f-953f-01a3-a8376b7be600', 'de', 'Sie stahl ihr den Anteil vom Opfer'),
('844f44c4-7a0f-953f-01a3-a8376b7be600', 'en', 'She stole her portion of the sacrifice'),
('2185e697-c375-11c1-12d2-fb7da2641938', 'de', 'Sie schloss sie vom Mahl aus'),
('2185e697-c375-11c1-12d2-fb7da2641938', 'en', 'She shut her out from the feast'),
('d593280a-e178-6e70-2bc6-a8cb9070d93a', 'de', 'Sie verspottete Elkanas Liebe zu ihr'),
('d593280a-e178-6e70-2bc6-a8cb9070d93a', 'en', 'She mocked Elkanah''s love for her'),
('38d822c9-beb8-2eeb-dda6-f7294cb599b3', 'de', 'Sie kränkte sie, weil der HERR ihren Leib verschlossen hatte'),
('38d822c9-beb8-2eeb-dda6-f7294cb599b3', 'en', 'She provoked her because the LORD had closed her womb'),
('b314f28e-8deb-2f89-8b98-bffaefc16e5e', 'de', 'Hast du beim Priester gefleht?'),
('b314f28e-8deb-2f89-8b98-bffaefc16e5e', 'en', 'Have you pleaded with the priest?'),
('7ef37138-5ba7-4211-4fe6-ee965caa7b97', 'de', 'Warum weinst du am Tor des Herrn?'),
('7ef37138-5ba7-4211-4fe6-ee965caa7b97', 'en', 'Why do you weep at the door of the Lord?'),
('30a5b975-a7cc-b27f-3c65-226414c4ee8d', 'de', 'Bin ich dir nicht mehr als zehn Söhne?'),
('30a5b975-a7cc-b27f-3c65-226414c4ee8d', 'en', 'Am I not more to you than ten sons?'),
('d155ee28-9584-094a-7043-77cd0859a34d', 'de', 'Willst du nicht ein zweites Weib nehmen?'),
('d155ee28-9584-094a-7043-77cd0859a34d', 'en', 'Will you not take a second wife?'),
('abda24cb-3160-6cb0-5950-8120e2bae34e', 'de', 'Ihre Lippen bewegten sich, doch man hörte keine Stimme'),
('abda24cb-3160-6cb0-5950-8120e2bae34e', 'en', 'Her lips moved but no voice was heard'),
('58c18346-b3d5-fc36-ccb7-5dc4ad026698', 'de', 'Sie schüttete Wein vor dem Altar aus'),
('58c18346-b3d5-fc36-ccb7-5dc4ad026698', 'en', 'She poured out wine before the altar'),
('12678d4a-a2e3-800b-d76f-43d892225388', 'de', 'Sie sang laut und taumelte'),
('12678d4a-a2e3-800b-d76f-43d892225388', 'en', 'She sang loudly and staggered'),
('8922d00b-e123-a079-9557-365d7458b47f', 'de', 'Sie schlief an den Türpfosten'),
('8922d00b-e123-a079-9557-365d7458b47f', 'en', 'She slept against the doorposts'),
('bc46a196-d85e-28b6-43de-1305365f46f6', 'de', 'Kein Schermesser solle auf sein Haupt kommen'),
('bc46a196-d85e-28b6-43de-1305365f46f6', 'en', 'No razor should touch his head'),
('90d8b0cc-806b-72b7-9fab-190b2cd72e92', 'de', 'Sie werde ihn zum Nasiräer in Silo weihen und opfern'),
('90d8b0cc-806b-72b7-9fab-190b2cd72e92', 'en', 'She would offer a ram in his stead'),
('11595b51-6a46-08fe-ecf5-1556bd970b30', 'de', 'Sie werde ihm ein Priestergewand weben'),
('11595b51-6a46-08fe-ecf5-1556bd970b30', 'en', 'She would weave him a priestly robe'),
('1126950e-8ebf-0801-299f-a31f3eeb8769', 'de', 'Er solle sieben Jahre im Tempel dienen'),
('1126950e-8ebf-0801-299f-a31f3eeb8769', 'en', 'He would serve seven years in the temple'),
('820b62de-10e2-48ca-f8c5-624dc8a1a426', 'de', 'Mit sieben Lämmern und Weihrauch'),
('820b62de-10e2-48ca-f8c5-624dc8a1a426', 'en', 'With seven lambs and incense'),
('c6ace0b4-a5f8-3fb5-5b7e-8ae4c0b6321f', 'de', 'Mit einem Zelt und einem Leuchter'),
('c6ace0b4-a5f8-3fb5-5b7e-8ae4c0b6321f', 'en', 'With a tent and a lampstand'),
('94125f08-9a07-43cf-7e5c-bda0d29c2640', 'de', 'Mit zwei Turteltauben und Öl'),
('94125f08-9a07-43cf-7e5c-bda0d29c2640', 'en', 'With two turtledoves and oil'),
